static inline int atomic_add_return(int i, atomic_t *v) /* <=== atomic_add_return */ 
{
	int val;
	smp_mb();  /* barrier for proper semantics */
	val = __insn_fetchadd4((void *)&v->counter, i) + i;
	barrier();  /* the "+ i" above will wait on memory */
	return val;
}

